import tkinter as tkimport shutil"""Faire un exe:pip install pyinstallerpyinstaller --onefile --noconsole monitor_disk.py=> dist/monitor_disk.exe (9Mo)taskkill /F /IM monitor_disk.exe"""REFRESH_MS = 5000RIGHT_MARGIN = 270TOP_MARGIN = -2def get_free_space(drive):    try:        free = shutil.disk_usage(drive).free        return free / (1024 ** 3)    except Exception:        return Nonedef update():    c = get_free_space("C:\\")    d = get_free_space("D:\\")    parts = []    if c is not None:        parts.append(f"C: {c:.1f} Go")    else:        parts.append("C: ?")    if d is not None:        parts.append(f"D: {d:.1f} Go")    else:        parts.append("D: ?")    label.config(text="    ".join(parts))    root.after(REFRESH_MS, update)# ---------------------------------------------------------# Déplacement de la fenêtre# ---------------------------------------------------------drag_x = 0drag_y = 0def start_move(event):    global drag_x, drag_y    # Position de la souris à l'intérieur de la fenêtre    drag_x = event.x    drag_y = event.ydef move_window(event):    x = root.winfo_x() + event.x - drag_x    y = root.winfo_y() + event.y - drag_y    root.geometry(f"+{x}+{y}")# ---------------------------------------------------------# Fenêtre# ---------------------------------------------------------root = tk.Tk()root.overrideredirect(True)       # pas de bordure / barre de titreroot.attributes("-topmost", True) # toujours au-dessusroot.attributes("-alpha", 0.80)   # transparenceroot.configure(bg="black")# ---------------------------------------------------------# Label# ---------------------------------------------------------label = tk.Label(    root,    text="",    font=("Segoe UI", 8),    fg="white",    bg="gray",    padx=2,    pady=0)label.pack()# ---------------------------------------------------------# Activation du déplacement# ---------------------------------------------------------# Sur la fenêtreroot.bind("<Button-1>", start_move)root.bind("<B1-Motion>", move_window)# Sur le label égalementlabel.bind("<Button-1>", start_move)label.bind("<B1-Motion>", move_window)# ---------------------------------------------------------# Force le calcul de la taille# ---------------------------------------------------------root.update_idletasks()# ---------------------------------------------------------# Position haut-droite# ---------------------------------------------------------screen_width = root.winfo_screenwidth()window_width = root.winfo_width()x = screen_width - window_width - RIGHT_MARGINy = TOP_MARGINroot.geometry(f"+{x}+{y}")# ---------------------------------------------------------# Arrondi v2# ---------------------------------------------------------"""root.update_idletasks()make_rounded(    root.winfo_id(),    root.winfo_width(),    root.winfo_height(),    10)"""# ---------------------------------------------------------# Démarrage# ---------------------------------------------------------update()root.mainloop()